mapper.select:
select notice_id as noticeId, notice_title as noticeTitle, notice_type as noticeType, cast(notice_content as char) as noticeContent, status, create_by as createBy, create_time as createTime, update_by as updateBy, update_time as updateTime, remark from sys_notice
and notice_title like concat('%', #{notice.noticeTitle}, '%')
and notice_type = #{notice.noticeType}
and create_by like concat('%', #{notice.createBy}, '%')
and status = #{notice.status}
order by create_time desc, notice_id desc
